-- 0080. Remove the two test breeder accounts before launch (Alex, 2026-10-31: "remove all of the test accounts").
-- 01M5XAWP63WNA5CBSFZNW9CCJM is removed-puppy-connection-test@breeders.test, suspended, no puppies.
-- 01M690E7V686H51DYXB597B8XZ is a pending sign-up made while testing, no puppies.
-- These are the only breeder rows whose id does not start with seed-, and the tables and their order are the ones
-- lib/demo.js wipeStatements uses for the same job. Every statement names the two ids, so a second run changes nothing.
-- Their sessions and sign-in links go with them. The seed-* breeders with @breeders.test addresses are
-- real kennels waiting for their invitation, not test accounts.
DELETE FROM disputes WHERE checkout_id IN (SELECT id FROM checkouts WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ')) OR payment_intent IN (SELECT stripe_payment_intent_id FROM payments WHERE checkout_id IN (SELECT id FROM checkouts WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ')));
DELETE FROM payments WHERE checkout_id IN (SELECT id FROM checkouts WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ'));
DELETE FROM sim_sessions WHERE client_reference_id IN (SELECT id FROM checkouts WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ'));
DELETE FROM puppy_holds WHERE checkout_id IN (SELECT id FROM checkouts WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ')) OR puppy_id IN (SELECT id FROM puppies WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ'));
DELETE FROM checkout_items WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ');
DELETE FROM checkouts WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ');
DELETE FROM photos WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ');
DELETE FROM puppy_videos WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ');
DELETE FROM documents WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ');
DELETE FROM puppies WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ');
DELETE FROM litters WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ');
