DELETE FROM account_requests WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ');
DELETE FROM listing_reports WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ');
DELETE FROM breeder_members WHERE breeder_id IN ('01M5XAWP63WNA5CBSFZNW9CCJM', '01M690E7V686H51DYXB597B8XZ');
